<?php

declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';

use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\TicketCheckoutService;

$pdo=Database::connection();$eventSlug=trim((string)($_GET['evento']??''));$tenantSlug=trim((string)($_GET['empresa']??''));$error=null;
if($tenantSlug===''){$s=$pdo->prepare('SELECT COUNT(*) FROM events e JOIN tenants t ON t.id=e.tenant_id WHERE e.slug=? AND e.status="published" AND t.status="active"');$s->execute([$eventSlug]);if((int)$s->fetchColumn()!==1){http_response_code(404);exit('Informe a empresa do evento.');}$s=$pdo->prepare('SELECT e.*,t.name tenant_name,t.slug tenant_slug,t.primary_color,t.secondary_color FROM events e JOIN tenants t ON t.id=e.tenant_id WHERE e.slug=? AND e.status="published" AND t.status="active" LIMIT 1');$s->execute([$eventSlug]);}
else{$s=$pdo->prepare('SELECT e.*,t.name tenant_name,t.slug tenant_slug,t.primary_color,t.secondary_color FROM events e JOIN tenants t ON t.id=e.tenant_id WHERE t.slug=? AND e.slug=? AND e.status="published" AND t.status="active" LIMIT 1');$s->execute([$tenantSlug,$eventSlug]);}
$event=$s->fetch();if(!$event){http_response_code(404);exit('Evento não encontrado.');}
try{$m=$pdo->prepare('SELECT enabled FROM tenant_modules WHERE tenant_id=? AND module_key="events" LIMIT 1');$m->execute([$event['tenant_id']]);$v=$m->fetchColumn();if($v!==false&&!(bool)$v){http_response_code(404);exit('Eventos indisponíveis.');}}catch(Throwable){}
$b=$pdo->prepare('SELECT * FROM ticket_batches WHERE event_id=? AND active=1 ORDER BY id');$b->execute([$event['id']]);$batches=$b->fetchAll();
$selectionKey='event_checkout:'.(int)$event['tenant_id'].':'.(int)$event['id'];if(!isset($_SESSION[$selectionKey])||!is_array($_SESSION[$selectionKey]))$_SESSION[$selectionKey]=[];$selection=&$_SESSION[$selectionKey];$step=$selection?2:1;if(isset($_GET['back'])){$step=1;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sessão expirada. Atualize a página.';else try{$action=(string)($_POST['action']??'');
  if($action==='select'){$quantities=(array)($_POST['quantity']??[]);$clean=[];$total=0;foreach($quantities as$id=>$qty){$id=(int)$id;$qty=max(0,min(10,(int)$qty));if($id>0&&$qty>0){$clean[$id]=$qty;$total+=$qty;}}if(!$clean)throw new RuntimeException('Escolha pelo menos um ingresso.');if($total>20)throw new RuntimeException('O limite por compra é de 20 ingressos.');$selection=$clean;$step=2;}
  elseif($action==='checkout'){if(!$selection)throw new RuntimeException('Escolha os ingressos novamente.');$reservation=(new TicketCheckoutService())->reserveMultiplePublic((int)$event['id'],$selection,['name'=>(string)($_POST['name']??''),'email'=>(string)($_POST['email']??''),'phone'=>(string)($_POST['phone']??'')],trim((string)($_POST['coupon']??''))?:null,trim((string)($_POST['promoter']??''))?:null);$selection=[];header('Location: '.app_url('/pedido.php?t='.rawurlencode($reservation['public_token'])),true,303);exit;}
 }catch(Throwable$e){$error=$e->getMessage();}
}
function legacy_event_money(int$c):string{return'R$ '.number_format($c/100,2,',','.');}
$primary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($event['primary_color']??''))?(string)$event['primary_color']:'#6d4aff';$secondary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($event['secondary_color']??''))?(string)$event['secondary_color']:'#8b5cf6';$selectedLines=[];$selectedSubtotal=0;foreach($batches as$batch){$qty=(int)($selection[(int)$batch['id']]??0);if($qty>0){$line=(int)$batch['price_cents']*$qty;$selectedSubtotal+=$line;$selectedLines[]=['batch'=>$batch,'qty'=>$qty,'total'=>$line];}}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="<?= Security::e($primary) ?>"><title><?= Security::e($event['name']) ?> — EventMenu</title><link rel="stylesheet" href="<?= Security::e(app_url('/assets/app.css')) ?>?v=92legacy-event2"><style>
:root{--event-primary:<?= Security::e($primary) ?>;--event-secondary:<?= Security::e($secondary) ?>}.legacy-event-page{margin:0;background:#f5f4f8;color:#20202b;font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}.event-public-top{height:66px;background:#17121f;color:#fff;display:flex;align-items:center}.event-public-top>div{width:min(1180px,100%);margin:auto;padding:0 18px;display:flex;justify-content:space-between;align-items:center}.event-public-logo{font-weight:950;letter-spacing:-.5px}.event-public-logo span{color:#9c84ff}.event-public-hero{position:relative;min-height:440px;background:linear-gradient(135deg,#1a1128,var(--event-primary));color:#fff;background-size:cover;background-position:center;display:flex;align-items:end}.event-public-hero:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,#0e091433 0,#0e0914b8 72%,#0e0914ee 100%)}.event-public-hero-inner{position:relative;z-index:2;width:min(1180px,100%);margin:auto;padding:70px 18px 46px}.event-public-hero h1{font-size:clamp(38px,8vw,76px);line-height:.95;margin:12px 0 18px;max-width:900px}.event-public-meta{display:flex;gap:20px;flex-wrap:wrap;font-size:14px;color:#ded8e8}.event-public-desc{max-width:760px;color:#cec7d7;line-height:1.6;margin-top:18px}.event-checkout{width:min(980px,calc(100% - 28px));margin:28px auto 70px}.event-stepper{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin-bottom:20px}.event-step{text-align:center;color:#97929f;font-size:10px;font-weight:800}.event-step b{width:31px;height:31px;border-radius:50%;display:grid;place-items:center;margin:0 auto 6px;background:#e8e5ed;color:#777181}.event-step.active b,.event-step.done b{background:var(--event-primary);color:#fff}.event-step.done{color:#6657a5}.event-check-card{background:#fff;border:1px solid #e7e4ec;border-radius:18px;padding:22px;box-shadow:0 8px 30px #31263f0d}.event-check-card h2{margin:0 0 5px}.ticket-choice-list{display:grid;gap:10px;margin-top:18px}.ticket-choice{display:grid;grid-template-columns:1fr 145px 150px;gap:15px;align-items:center;border:1px solid #ebe8ef;border-radius:14px;padding:16px}.ticket-choice h3{margin:0 0 4px;font-size:16px}.ticket-choice small{color:#8b8793}.ticket-price{font-size:18px;font-weight:950;color:var(--event-primary)}.ticket-qty{display:flex;align-items:center;justify-content:flex-end;gap:7px}.ticket-qty button{width:36px;height:36px;padding:0;border-radius:10px;background:#f0edf7;color:#5e48bf}.ticket-qty input{width:55px;text-align:center;min-height:36px;padding:6px}.event-buy{margin-top:18px;width:100%;background:var(--event-primary);color:#fff;border:0;border-radius:13px;min-height:50px;font-weight:900}.event-summary{display:grid;gap:9px;margin:17px 0}.event-summary-line{display:flex;justify-content:space-between;gap:12px;padding-bottom:9px;border-bottom:1px solid #efedf2}.event-summary-line.total{font-size:18px;border:0;padding-top:5px}.event-buyer-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.event-buyer-grid .full{grid-column:1/-1}.event-buyer-grid label{font-size:11px}.event-actions{display:flex;gap:9px;margin-top:16px}.event-actions>*{flex:1}.event-actions .primary{background:var(--event-primary)}@media(max-width:650px){.event-public-hero{min-height:370px}.event-public-hero-inner{padding-bottom:35px}.event-public-meta{gap:9px;font-size:11px}.event-checkout{width:calc(100% - 20px)}.event-check-card{padding:15px}.ticket-choice{grid-template-columns:1fr auto;gap:8px}.ticket-price{grid-column:1}.ticket-qty{grid-column:2;grid-row:1/3}.event-step{font-size:8px}.event-buyer-grid{grid-template-columns:1fr}.event-buyer-grid .full{grid-column:1}.event-actions{flex-direction:column}}
</style></head><body class="legacy-event-page"><header class="event-public-top"><div><div class="event-public-logo">EVENTMENU <span>PREMIUM</span></div><span><?= Security::e($event['tenant_name']) ?></span></div></header><section class="event-public-hero"<?= $event['banner_url']?' style="background-image:url(\''.Security::e($event['banner_url']).'\')"':'' ?>><div class="event-public-hero-inner"><div style="font-size:11px;text-transform:uppercase;letter-spacing:.16em;font-weight:900;color:#c8baff">Evento</div><h1><?= Security::e($event['name']) ?></h1><div class="event-public-meta"><strong>📅 <?= Security::e(date('d/m/Y \à\s H:i',strtotime($event['starts_at']))) ?></strong><span>📍 <?= Security::e($event['venue']??'') ?></span><?php if(!empty($event['address'])):?><span><?= Security::e($event['address']) ?></span><?php endif;?></div><?php if(!empty($event['description'])):?><div class="event-public-desc"><?= nl2br(Security::e($event['description'])) ?></div><?php endif;?></div></section><main class="event-checkout"><div class="event-stepper"><div class="event-step <?= $step>=1?'active':'' ?>"><b>1</b>Ingressos</div><div class="event-step <?= $step===2?'active':'' ?>"><b>2</b>Dados</div><div class="event-step"><b>3</b>Pagamento</div><div class="event-step"><b>4</b>Confirmação</div></div><?php if($error):?><div class="alert error"><?= Security::e($error) ?></div><?php endif;?><?php if($step===1):?><section class="event-check-card"><h2>Ingressos</h2><p class="muted">Escolha os ingressos e as quantidades.</p><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="select"><div class="ticket-choice-list"><?php foreach($batches as$batch):$available=max(0,(int)$batch['quantity_total']-(int)$batch['quantity_sold']-(int)$batch['quantity_reserved']);$now=time();$open=(!$batch['sales_start']||strtotime($batch['sales_start'])<=$now)&&(!$batch['sales_end']||strtotime($batch['sales_end'])>=$now);?><article class="ticket-choice"><div><h3><?= Security::e($batch['name']) ?></h3><small><?= $available ?> disponíveis<?= !$open?' · Fora do período de venda':'' ?></small></div><div class="ticket-price"><?= legacy_event_money((int)$batch['price_cents']) ?></div><div class="ticket-qty"><button type="button" data-minus>-</button><input type="number" name="quantity[<?= (int)$batch['id'] ?>]" min="0" max="<?= min(10,$available) ?>" value="0"<?= (!$open||$available<1)?' disabled':'' ?>><button type="button" data-plus<?= (!$open||$available<1)?' disabled':'' ?>>+</button></div></article><?php endforeach;?><?php if(!$batches):?><p class="muted">Vendas ainda não abertas.</p><?php endif;?></div><?php if($batches):?><button class="event-buy">Comprar Agora</button><?php endif;?></form></section><?php else:?><section class="event-check-card"><h2>Checkout</h2><p class="muted">Confira os ingressos e preencha os dados do titular da compra.</p><div class="event-summary"><?php foreach($selectedLines as$line):?><div class="event-summary-line"><span><?= Security::e($line['batch']['name']) ?><br><small class="muted"><?= (int)$line['qty'] ?> × <?= legacy_event_money((int)$line['batch']['price_cents']) ?></small></span><strong><?= legacy_event_money($line['total']) ?></strong></div><?php endforeach;?><div class="event-summary-line total"><strong>Total</strong><strong style="color:var(--event-primary)"><?= legacy_event_money($selectedSubtotal) ?></strong></div></div><form method="post" class="event-buyer-grid"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="checkout"><label class="full">Nome completo<input name="name" required autocomplete="name"></label><label>E-mail<input type="email" name="email" autocomplete="email"></label><label>Telefone<input name="phone" autocomplete="tel"></label><label>Cupom<input name="coupon" placeholder="Opcional"></label><label>Promotor / afiliado<input name="promoter" placeholder="Opcional"></label><div class="event-actions full"><a class="button secondary" href="<?= Security::e(app_url('/evento.php?empresa='.urlencode((string)$event['tenant_slug']).'&evento='.urlencode((string)$event['slug']).'&back=1')) ?>">Voltar</a><button class="primary">Continuar para pagamento</button></div></form></section><?php endif;?></main><script>document.querySelectorAll('.ticket-qty').forEach(box=>{const input=box.querySelector('input'),minus=box.querySelector('[data-minus]'),plus=box.querySelector('[data-plus]');if(!input)return;minus?.addEventListener('click',()=>{input.value=Math.max(Number(input.min||0),Number(input.value||0)-1)});plus?.addEventListener('click',()=>{input.value=Math.min(Number(input.max||10),Number(input.value||0)+1)});});</script></body></html>
